--
-- Structure for view "student_due_Report_vw"
--
DROP TABLE IF EXISTS "student_due_Report_vw";

CREATE OR REPLACE VIEW "student_due_Report_vw"  AS SELECT "s"."student_id" AS "student_id", concat("s"."student_first_name",' ',"s"."student_last_name") AS "student_name", "s"."Class" AS "Class", "s"."section" AS "section", "s"."campus" AS "campus", sum("f"."balance") AS "section_due_amount", max("f"."payment_date") AS "last_payment_date", "f"."feesMonth" AS "feesMonth" FROM ("student" "s" join "fees_collection" "f" on("s"."student_id" = "f"."student_id")) GROUP BY "s"."student_id", "s"."student_first_name", "s"."student_last_name", "s"."Class", "s"."section", "s"."campus", "f"."feesMonth" HAVING sum("f"."balance") > 0 ORDER BY "s"."student_id" ASC, "f"."feesMonth" ASC ;

--
-- Constraints for dumped tables
--

--
-- Constraints for table "invoice"
--
ALTER TABLE "invoice" ADD CONSTRAINT "fk_invoice_quotation" FOREIGN KEY ("quotation_id") REFERENCES "quotation" ("quotation_id") ON UPDATE CASCADE;

--
-- Constraints for table "quotation_item"
--
ALTER TABLE "quotation_item" ADD CONSTRAINT "fk_quotation_item" FOREIGN KEY ("quotation_id") REFERENCES "quotation" ("quotation_id") ON DELETE CASCADE ON UPDATE CASCADE;

--
-- Constraints for table "store_product_item"
--
ALTER TABLE "store_product_item" ADD CONSTRAINT "fk_product_item" FOREIGN KEY ("product_id") REFERENCES "store_product" ("product_id") ON DELETE CASCADE ON UPDATE CASCADE;

